package vn.xuannhashop.infrastructure.persistence;
import java.util.*;import org.springframework.stereotype.Repository;
import vn.xuannhashop.business.delivery.application.*;import vn.xuannhashop.business.delivery.application.DeliveryPlanningApplication.*;
import vn.xuannhashop.business.shared.DomainException;import static vn.xuannhashop.infrastructure.persistence.Sql.p;
@Repository public class JdbcDeliveryPlanningRepository implements DeliveryPlanningRepository {
    private final Sql s;public JdbcDeliveryPlanningRepository(Sql s){this.s=s;}
    public Map<String,Object> overview(String assignee){return Map.of("guides",s.rows("select distinct on(g.type_id) g.*,t.name type_name from equipment_guide g join equipment_type t on t.id=g.type_id order by g.type_id,g.version desc",Map.of()),"staff",s.rows("select username,display_name from user_account where enabled and role='DELIVERY' order by display_name",Map.of()),"assignments",s.rows("select a.*,o.code order_code,o.address current_address,o.version current_order_version,o.status order_status,u.display_name assignee_name from delivery_assignment a join rental_order o on o.id=a.order_id join user_account u on u.username=a.assignee where cast(:a as text) is null or a.assignee=:a order by a.starts_at desc limit 300",p("a",assignee)));}
    public void lockGuide(UUID type){s.rows("select pg_advisory_xact_lock(hashtextextended(:key,0))",p("key","guide:"+type));if(s.one("select id from equipment_type where id=:id",p("id",type))==null)throw DomainException.missing();}
    public Map<String,Object> guide(UUID type){return s.one("select * from equipment_guide where type_id=:id order by version desc limit 1",p("id",type));}
    public void publish(UUID id,Guide c,String actor){s.update("insert into equipment_guide(id,type_id,version,title,instructions,safety,source,published_by) values(:id,:t,:v,:title,:i,:s,:source,:a)",p("id",id,"t",c.typeId(),"v",c.expectedVersion()+1,"title",c.title(),"i",c.instructions(),"s",c.safety(),"source",c.source(),"a",actor));}
    public List<Map<String,Object>> orderGuides(UUID order){return s.rows("select distinct e.type_id,t.name type_name,g.id,g.version,g.title,g.instructions,g.safety,g.source from rental_item i join equipment e on e.id=i.equipment_id join equipment_type t on t.id=e.type_id left join lateral (select * from equipment_guide where type_id=e.type_id order by version desc limit 1) g on true where i.order_id=:id order by e.type_id",p("id",order));}
    public List<Map<String,Object>> acknowledgements(UUID order){return s.rows("select a.*,g.type_id,g.version,g.title,g.instructions,g.safety,g.source from guide_acknowledgement a join equipment_guide g on g.id=a.guide_id where a.order_id=:id order by a.created_at desc",p("id",order));}
    public Map<String,Object> order(UUID id){return s.one("select * from rental_order where id=:id for update",p("id",id));}
    public void acknowledge(UUID id,UUID order,UUID guide,String confirmed,String evidence,String method,String actor){s.update("insert into guide_acknowledgement(id,order_id,guide_id,confirmed_by,recorded_by,method,evidence) values(:id,:o,:g,:c,:a,:m,:e)",p("id",id,"o",order,"g",guide,"c",confirmed,"a",actor,"m",method,"e",evidence));}
    public boolean missingAcknowledgement(UUID order,List<UUID> items){return s.one("select 1 from rental_item i join equipment e on e.id=i.equipment_id join lateral(select id from equipment_guide where type_id=e.type_id order by version desc limit 1) g on true where i.order_id=:o and i.id in (:items) and not exists(select 1 from guide_acknowledgement a where a.order_id=i.order_id and a.guide_id=g.id) limit 1",p("o",order,"items",items))!=null;}
    public boolean assignee(String name){return s.one("select username from user_account where username=:n and enabled and role='DELIVERY' for update",p("n",name))!=null;}
    public boolean overlap(Assignment c){return s.one("select id from delivery_assignment where assignee=:a and status='ASSIGNED' and starts_at<:t and ends_at>:f",p("a",c.assignee(),"f",c.startsAt(),"t",c.endsAt()))!=null;}
    public void assign(UUID id,Assignment c,String address,String actor){s.update("insert into delivery_assignment(id,order_id,kind,assignee,starts_at,ends_at,route_note,order_version,address_snapshot,assigned_by) values(:id,:o,:k,:a,:f,:t,:n,:v,:address,:actor)",p("id",id,"o",c.orderId(),"k",c.kind(),"a",c.assignee(),"f",c.startsAt(),"t",c.endsAt(),"n",c.routeNote(),"v",c.orderVersion(),"address",address,"actor",actor));}
    public Map<String,Object> assignment(UUID id){return s.one("select * from delivery_assignment where id=:id for update",p("id",id));}
    public boolean performed(UUID order,String kind){return s.one("select 1 where exists(select 1 from handover where order_id=:o and kind=:k) and not exists(select 1 from rental_item where order_id=:o and (case when :k='OUT' then handed_at is null else returned_at is null and resolved_at is null end))",p("o",order,"k",kind))!=null;}
    public void finish(UUID id,boolean completed,String outcome){s.update("update delivery_assignment set status=:s,outcome=:o,completed_at=clock_timestamp() where id=:id",p("id",id,"s",completed?"COMPLETED":"CANCELLED","o",outcome));}
}
